import React, { useState } from 'react';
import './MultimediaPlayer.css';

interface MultimediaPlayerProps {
  title?: string;
}

const MultimediaPlayer: React.FC<MultimediaPlayerProps> = ({ 
  title = "Contenido Multimedia" 
}) => {
  const [activeTab, setActiveTab] = useState<'youtube' | 'spotify' | 'apple'>('youtube');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedVideo, setSelectedVideo] = useState<string>('NuZO96z2ZVk');

  // Lista de videos del canal con títulos reales
  const youtubeVideos = [
    { id: 'NuZO96z2ZVk', title: 'Schumann Fantasie Stücke OP 73', description: 'Zart und mit Ausdruck' },
    { id: 'VvTeE16r7z4', title: 'Bach Cello Suite No.1', description: 'Prelude' },
    { id: 'ZQav1zSsm90', title: 'Beethoven Cello Sonata', description: 'Op. 69' },
    { id: 'w0Fc47FO7i8', title: 'Dvořák Cello Concerto', description: 'Allegro' },
    { id: '-r6pIQhZjXg', title: 'Elgar Cello Concerto', description: 'Adagio' },
    { id: 'rbgvnTy__LQ', title: 'Haydn Cello Concerto', description: 'Moderato' },
    { id: '9L-nwBjDIkE', title: 'Saint-Saëns Cello Concerto', description: 'Allegro non troppo' },
    { id: 'iMdpDBY2lTg', title: 'Boccherini Cello Concerto', description: 'Grave' },
    { id: 'UcyadELV0Dc', title: 'Shostakovich Cello Concerto', description: 'Allegretto' },
    { id: 'eQEzmprKg3g', title: 'Tchaikovsky Rococo Variations', description: 'Moderato' },
    { id: 'Ion6xwCULlA', title: 'Brahms Cello Sonata', description: 'Allegro vivace' },
    { id: '5_EW6GWwmC8', title: 'Schubert Arpeggione Sonata', description: 'Allegro moderato' },
    { id: 'v8MaYzRaRe8', title: 'Rachmaninoff Cello Sonata', description: 'Lento' }
  ];

  const [currentPage, setCurrentPage] = useState(0);
  const videosPerPage = 5;
  const totalPages = Math.ceil(youtubeVideos.length / videosPerPage);
  const currentVideos = youtubeVideos.slice(currentPage * videosPerPage, (currentPage + 1) * videosPerPage);

  const handleTabChange = (tab: 'youtube' | 'spotify' | 'apple') => {
    setIsLoading(true);
    setActiveTab(tab);
    
    // Simular carga para efecto visual
    setTimeout(() => {
      setIsLoading(false);
    }, 300);
  };

  const handleVideoSelect = (videoId: string) => {
    setSelectedVideo(videoId);
  };

  const renderYouTubeContent = () => (
    <div className="platform-content youtube-content">
      <div className="content-header">
        <h3>🎥 Canal de YouTube</h3>
        <p>Selecciona un video para reproducir</p>
      </div>
      
      {/* Video principal */}
      <div className="main-video-container">
        <iframe
          src={`https://www.youtube.com/embed/${selectedVideo}?autoplay=0&rel=0`}
          title="YouTube Video Player - Adolfo Gutiérrez Arenas"
          frameBorder="0"
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
          allowFullScreen
        ></iframe>
      </div>
      
      {/* Carrusel de miniaturas */}
      <div className="video-carousel">
        <h4>Selecciona otro video:</h4>
        <div className="thumbnail-grid">
          {youtubeVideos.map((video) => (
            <div
              key={video.id}
              className={`video-thumbnail ${selectedVideo === video.id ? 'selected' : ''}`}
              onClick={() => handleVideoSelect(video.id)}
            >
              <img
                src={video.thumbnail}
                alt={video.title}
                className="thumbnail-image"
              />
              <div className="thumbnail-overlay">
                <span className="play-icon">▶️</span>
              </div>
            </div>
          ))}
        </div>
      </div>
      
      <div className="platform-actions">
        <a 
          href="https://youtube.com/@gotieroify?feature=shared" 
          target="_blank" 
          rel="noopener noreferrer"
          className="platform-link youtube-link"
        >
          <span className="platform-icon">▶️</span>
          Ver Canal Completo
        </a>
      </div>
    </div>
  );

  const renderSpotifyContent = () => (
    <div className="platform-content spotify-content">
      <div className="content-header">
        <h3>🎵 Spotify</h3>
        <p>Escucha mi música en Spotify</p>
      </div>
      
      <div className="spotify-player">
        <iframe
          src="https://open.spotify.com/embed/artist/53pHVjb5WZG7Vrdrn5YrRv?utm_source=generator&theme=0"
          title="Spotify Player - Adolfo Gutiérrez Arenas"
          width="100%"
          height="400"
          frameBorder="0"
          allowTransparency={true}
          allow="encrypted-media"
        ></iframe>
      </div>
      
      <div className="platform-actions">
        <a 
          href="https://open.spotify.com/artist/53pHVjb5WZG7Vrdrn5YrRv?si=_hYftEZTTDeDQ7PulqiNDw" 
          target="_blank" 
          rel="noopener noreferrer"
          className="platform-link spotify-link"
        >
          <span className="platform-icon">🎧</span>
          Abrir en Spotify
        </a>
      </div>
    </div>
  );

  const renderAppleMusicContent = () => (
    <div className="platform-content apple-content">
      <div className="content-header">
        <h3>🍎 Apple Music</h3>
        <p>Disfruta mi música en Apple Music</p>
      </div>
      
      <div className="apple-player">
        <iframe
          allow="autoplay *; encrypted-media *; fullscreen *"
          title="Apple Music Player - Adolfo Gutiérrez Arenas"
          frameBorder="0"
          height="400"
          style={{ width: '100%', maxWidth: '660px', overflow: 'hidden', background: 'transparent' }}
          sandbox="allow-forms allow-popups allow-same-origin allow-scripts allow-top-navigation-by-user-activation"
          src="https://embed.music.apple.com/es/artist/adolfo-guti%C3%A9rrez-arenas/271698331"
        ></iframe>
      </div>
      
      <div className="platform-actions">
        <a 
          href="https://music.apple.com/es/artist/adolfo-guti%C3%A9rrez-arenas/271698331" 
          target="_blank" 
          rel="noopener noreferrer"
          className="platform-link apple-link"
        >
          <span className="platform-icon">🎼</span>
          Abrir en Apple Music
        </a>
      </div>
    </div>
  );

  const renderContent = () => {
    if (isLoading) {
      return (
        <div className="loading-container">
          <div className="loading-spinner"></div>
          <p>Cargando contenido...</p>
        </div>
      );
    }

    switch (activeTab) {
      case 'youtube':
        return renderYouTubeContent();
      case 'spotify':
        return renderSpotifyContent();
      case 'apple':
        return renderAppleMusicContent();
      default:
        return renderYouTubeContent();
    }
  };

  return (
    <section className="multimedia-player-section">
      <div className="multimedia-container">
        <div className="section-header">
          <h2 className="section-title">{title}</h2>
          <p className="section-subtitle">
            Explora mi contenido en diferentes plataformas musicales
          </p>
        </div>

        <div className="multimedia-player">
          <div className="tabs-container">
            <button
              className={`tab-button youtube-tab ${activeTab === 'youtube' ? 'active' : ''}`}
              onClick={() => handleTabChange('youtube')}
            >
              <span className="tab-icon">🎥</span>
              <span className="tab-text">YouTube</span>
            </button>
            
            <button
              className={`tab-button spotify-tab ${activeTab === 'spotify' ? 'active' : ''}`}
              onClick={() => handleTabChange('spotify')}
            >
              <span className="tab-icon">🎵</span>
              <span className="tab-text">Spotify</span>
            </button>
            
            <button
              className={`tab-button apple-tab ${activeTab === 'apple' ? 'active' : ''}`}
              onClick={() => handleTabChange('apple')}
            >
              <span className="tab-icon">🍎</span>
              <span className="tab-text">Apple Music</span>
            </button>
          </div>

          <div className="content-container">
            {renderContent()}
          </div>
        </div>
      </div>
    </section>
  );
};

export default MultimediaPlayer;
